import { Link } from 'react-router-dom';

function Navbar() {
  return (
    <div style={styles.navbar}>
      <h2 style={styles.title}>Event Booking</h2>

      <div>
        <Link to="/login" style={{ textDecoration: 'none' }}>
          <button style={styles.login}>Login</button>
        </Link>

        <Link to="/register" style={{ textDecoration: 'none' }}>
          <button style={styles.register}>Register</button>
        </Link>
      </div>
    </div>
  );
}

const styles = {
  navbar: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '16px 24px',
    background: '#ffffff',
    borderBottom: '1px solid #eee',
  },

  title: {
    color: '#c95f1e',
    fontWeight: '700',
    fontSize: '24px',
    margin: 0,
  },

  login: {
    marginRight: '10px',
    padding: '8px 16px',
    border: '1px solid #d97a3b',
    background: 'white',
    color: '#d97a3b',
    borderRadius: '8px',
    cursor: 'pointer',
  },

  register: {
    padding: '8px 16px',
    border: 'none',
    background: '#d97a3b',
    color: 'white',
    borderRadius: '8px',
    cursor: 'pointer',
  },
};

export default Navbar;
